return ['domain'=>NULL,'plural-forms'=>'nplurals=2; plural=n != 1;','language'=>'eo','project-id-version'=>'Babilim 1.0.0','pot-creation-date'=>'2026-10-31T05:53:07+00:00','po-revision-date'=>'2026-10-31T05:53:07+00:00','x-generator'=>'Babilim','messages'=>['Babilim'=>'Babilim','Fills in missing translations for the plugins and themes already installed on your site.'=>'Plenigas mankantajn tradukojn por la kromprogramoj kaj etosoj jam instalitaj en via retejo.','Translations'=>'Tradukoj','Babilim Settings'=>'Agordoj de Babilim','Settings'=>'Agordoj','You are not allowed to do this.'=>'Vi ne rajtas fari tion.','Select fewer components: at most %1$d operations per run (you selected %2$d).'=>'Elektu malpli da komponantoj: maksimume %1$d operacioj por ĉiu ruligo (vi elektis %2$d).','That component is not installed on this site, so a translation cannot be requested for it.'=>'Tiu komponanto ne estas instalita en ĉi tiu retejo, do traduko ne povas esti petita por ĝi.','Already installed.'=>'Jam instalita.','Downloaded and installed.'=>'Elŝutita kaj instalita.','Babilim has not been enabled for this site yet.'=>'Babilim ankoraŭ ne estas ebligita por ĉi tiu retejo.','No build is available to download for this locale.'=>'Neniu kompilaĵo estas elŝutebla por ĉi tiu lingvo.','Rolled back to the previous build.'=>'Retroigita al la antaŭa muntaĵo.','Rolled back and reported.'=>'Retroigita kaj raportita.','Rolled back, but the report could not be sent: %s'=>'Retroigita, sed la raporto ne povis esti sendita: %s','Removed.'=>'Forigita.','Translation requested.'=>'Traduko petita.','This component was already uploaded. Babilim is checking it now.'=>'Tiu komponanto jam estis alŝutita. Babilim kontrolas ĝin nun.','Upload cancelled.'=>'Alŝuto nuligita.','Upload complete — translation requested.'=>'Alŝuto finita — traduko petita.','This component does not declare a version number, so a translation cannot be requested for it.'=>'Tiu komponanto ne deklaras versionumeron, do traduko ne povas esti petita por ĝi.','This component\'s version number is longer than %d characters, which Babilim cannot handle, so a translation cannot be requested for it.'=>'La versionumero de tiu komponanto estas pli longa ol %d signoj, kion Babilim ne povas trakti, do traduko ne povas esti petita por ĝi.','A translation cannot be requested for that locale on this site right now.'=>'Traduko ne povas esti petita por tiu lingvo en ĉi tiu retejo nuntempe.','Thank you. Your report was sent.'=>'Dankon. Via raporto estis sendita.','This report does not name a valid plugin or theme and locale.'=>'Ĉi tiu raporto ne enhavas validan Nomon de kromprogramo aŭ etoso kaj lingvo.','Please choose a category for this report.'=>'Bonvolu elekti kategorion por ĉi tiu raporto.','This report is missing a valid build to report against.'=>'Al ĉi tiu raporto mankas valida kompilaĵo, pri kiu raporti.','This build is not one this site currently knows about for this component/locale.'=>'Ĉi tiu kompilaĵo ne estas konata de ĉi tiu retejo por ĉi tiu komponanto/lingvo.','The field "%1$s" is too long: it has %2$d characters and the limit is %3$d. Nothing was sent; please shorten it and try again.'=>'La kampo "%1$s" estas tro longa: ĝi havas %2$d signojn kaj la limo estas %3$d. Nenio estis sendita; bonvolu mallongigi ĝin kaj reprovi.','Original string'=>'Originala teksto','String context'=>'Kunteksto de la teksto','Current translation'=>'Nuna traduko','Suggested translation'=>'Sugestita traduko','Note (optional)'=>'Noto (nedeviga)','Where you saw this (optional)'=>'Kie vi vidis tion (nedeviga)','Babilim sync is temporarily delayed by the service (rate limited); it will try again after %s.'=>'La sinkronigo de Babilim estas portempe prokrastita de la servo (limigo de petoj); ĝi reprovos post %s.','That is not a valid WordPress locale code. Nothing was saved.'=>'Tio ne estas valida lingva kodo de WordPress. Nenio estis konservita.','Settings saved.'=>'Agordoj konservitaj.','If this is on, uninstalling also erases this site\'s identity. The paid license attached to this site cannot be restored automatically afterwards; you would have to contact Babilim support at %s to get it back.'=>'Se tio estas ŝaltita, malinstalo ankaŭ forigas la identecon de ĉi tiu retejo. La pagita licenco ligita al ĉi tiu retejo poste ne povos esti restaŭrita aŭtomate; vi devus kontakti la subtenon de Babilim ĉe %s por rehavi ĝin.','Babilim is set to erase this site\'s identity when the plugin is deleted. The paid license attached to this site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in the Babilim settings, and deactivate again. Deactivate anyway?'=>'Babilim estas agordita forigi la identecon de ĉi tiu retejo kiam la kromprogramo estas forigita. La pagita licenco ligita al ĉi tiu retejo poste ne povus esti restaŭrita aŭtomate; vi devus kontakti la subtenon de Babilim ĉe %s. Por konservi la identecon, premu Nuligi, malmarku "Forigi ĉiujn datumojn de Babilim ĉe malinstalo" en la agordoj de Babilim, kaj malaktivigu denove. Ĉu malaktivigi tamen?','%1$d site on this network is set to erase its Babilim identity when the plugin is deleted. The paid license attached to that site could then not be restored automatically; you would have to contact Babilim support at %2$s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in that site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'%1$d retejo en ĉi tiu reto estas agordita forigi sian identecon de Babilim kiam la kromprogramo estas forigita. La pagita licenco ligita al tiu retejo poste ne povus esti restaŭrita aŭtomate; vi devus kontakti la subtenon de Babilim ĉe %2$s. Por konservi la identecon, premu Nuligi, malmarku "Forigi ĉiujn datumojn de Babilim ĉe malinstalo" en la agordoj de Babilim de tiu retejo, kaj malaktivigu denove. Ĉu malaktivigi tamen?' . "\0" . '%1$d retejoj en ĉi tiu reto estas agorditaj forigi sian identecon de Babilim kiam la kromprogramo estas forigita. La pagita licenco ligita al tiuj retejoj poste ne povus esti restaŭrita aŭtomate; vi devus kontakti la subtenon de Babilim ĉe %2$s. Por konservi la identecojn, premu Nuligi, malmarku "Forigi ĉiujn datumojn de Babilim ĉe malinstalo" en la agordoj de Babilim de ĉiu retejo, kaj malaktivigu denove. Ĉu malaktivigi tamen?','This network has too many sites to check them one by one, and some of them may be set to erase their Babilim identity when the plugin is deleted. The paid license attached to such a site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identities, press Cancel, untick "Delete all Babilim data on uninstall" in each site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'Ĉi tiu reto havas tro multajn retejojn por kontroli ilin unuope, kaj kelkaj el ili povas esti agorditaj forigi sian identecon de Babilim kiam la kromprogramo estas forigita. La pagita licenco ligita al tia retejo poste ne povus esti restaŭrita aŭtomate; vi devus kontakti la subtenon de Babilim ĉe %s. Por konservi la identecojn, premu Nuligi, malmarku "Forigi ĉiujn datumojn de Babilim ĉe malinstalo" en la agordoj de Babilim de ĉiu retejo, kaj malaktivigu denove. Ĉu malaktivigi tamen?','Open Babilim settings'=>'Malfermi la agordojn de Babilim','Babilim could not verify this site, so nothing is downloaded or installed.'=>'Babilim ne povis kontroli ĉi tiun retejon, do nenio estas elŝutita aŭ instalita.','The service could not reach your site. A firewall, security plugin or host rule is probably blocking the request; please allow requests to /wp-json/babilim/v1/challenge.'=>'La servo ne povis atingi vian retejon. Fajroŝirmilo, sekureca kromprogramo aŭ regulo de la gastiganto verŝajne blokas la peton; bonvolu permesi petojn al /wp-json/babilim/v1/challenge.','Your site took too long to answer. Please try again later, and check that your host is not too slow or overloaded.'=>'Via retejo respondis tro malrapide. Bonvolu reprovi poste, kaj kontrolu ĉu via gastiganto ne estas tro malrapida aŭ troŝarĝita.','Your site answered, but not with what was expected. The REST API may be rewritten by another plugin, or that endpoint may be cached; please exclude /wp-json/babilim/v1/challenge from caching and rewriting.'=>'Via retejo respondis, sed ne per la atendata enhavo. La REST-API eble estas reskribita de alia kromprogramo, aŭ tiu finpunkto eble estas kaŝmemorigita; bonvolu ekskludi /wp-json/babilim/v1/challenge el kaŝmemorado kaj reskribado.','Please check that your site can be reached from the internet, then try again.'=>'Bonvolu kontroli ĉu via retejo estas atingebla de la interreto, poste reprovu.','Re-verify'=>'Re-kontroli','This site is over the size the service accepts in one sync, so some items were left out: %1$d components and %2$d locales.'=>'Ĉi tiu retejo superas la grandecon kiun la servo akceptas en unu sinkronigo, do kelkaj eroj estis preterlasitaj: %1$d komponantoj kaj %2$d lokaĵaroj.','This site is verified.'=>'Ĉi tiu retejo estas konfirmita.','Registration restarted.'=>'Registrado rekomencita.','Sync complete.'=>'Sinkronigo finita.','Babilim is enabling and checking this site… Reload this page or wait for the scheduled check to finish.'=>'Babilim ebligas kaj kontrolas ĉi tiun retejon… Reŝargu ĉi tiun paĝon aŭ atendu ke la planita kontrolo finiĝu.','Babilim could not finish enabling (%1$s): %2$s'=>'Babilim ne povis fini la ebligon (%1$s): %2$s','A host that serves only one PHP request at a time cannot complete this step.'=>'Gastiganto kiu servas nur unu PHP-peton samtempe ne povas plenumi ĉi tiun paŝon.','Babilim is enabled: this site is verified and %d component was found.'=>'Babilim estas ŝaltita: ĉi tiu retejo estas konfirmita kaj %d komponanto estis trovita.' . "\0" . 'Babilim estas ŝaltita: ĉi tiu retejo estas konfirmita kaj %d komponantoj estis trovitaj.','Babilim is disabled. Nothing more is sent; translations already installed keep working.'=>'Babilim estas malebligita. Nenio plu estas sendata; jam instalitaj tradukoj daŭre funkcias.','Supplementary translation index rebuilt.'=>'Komplementa traduka indekso rekonstruita.','Sweep complete: %d file deleted.'=>'Skanado finita: %d dosiero forigita.' . "\0" . 'Skanado finita: %d dosieroj forigitaj.','Removed %d installed component.'=>'Forigita %d instalita komponanto.' . "\0" . 'Forigitaj %d instalitaj komponantoj.','Automatic installs are now off; turn them on again in the settings if you want them.'=>'Aŭtomataj instaloj nun estas malŝaltitaj; ŝaltu ilin denove en la agordoj, se vi volas ilin.','Babilim finds the plugins and themes on this site that have no translation for your language and installs one for each.'=>'Babilim trovas la kromprogramojn kaj temojn en ĉi tiu retejo kiuj ne havas tradukon por via lingvo kaj instalas unu por ĉiu.','Languages found on this site: %s.'=>'Lingvoj trovitaj en ĉi tiu retejo: %s.','Available translations can be installed with one click, and missing ones can be requested. After that, new translations and updates are installed automatically (on the free plan, only for plugins and themes that already use a free slot).'=>'Haveblaj tradukoj povas esti instalitaj per unu alklako, kaj mankantaj povas esti petitaj. Poste novaj tradukoj kaj ĝisdatigoj estas instalitaj aŭtomate (en la senpaga plano, nur por kromprogramoj kaj etosoj, kiuj jam uzas senpagan lokon).','The free plan covers a limited number of plugins and themes; your exact quota is shown in Settings after you enable Babilim.'=>'La senpaga plano kovras limigitan nombron de kromprogramoj kaj etosoj; via preciza kvoto estas montrata en Agordoj post kiam vi ŝaltos Babilim.','What is sent when you enable Babilim'=>'Kio estas sendata kiam vi ŝaltas Babilim','Enabling…'=>'Ebligado…','Enable Babilim'=>'Ŝalti Babilim','By clicking Enable, you agree to send the information listed above to Babilim.'=>'Klakante Ebligi, vi konsentas sendi la supre listigitajn informojn al Babilim.','Check again now'=>'Kontroli denove nun','Babilim installed %d translation automatically since your last visit.'=>'Babilim aŭtomate instalis %d tradukon ekde via lasta vizito.' . "\0" . 'Babilim aŭtomate instalis %d tradukojn ekde via lasta vizito.','Babilim is enabling and checking this site… (last attempt: %s)'=>'Babilim ebligas kaj kontrolas ĉi tiun retejon… (lasta provo: %s)','Check again'=>'Kontroli denove','No components synced yet.'=>'Ankoraŭ neniu komponanto sinkronigita.','%d succeeded'=>'%d sukcesis' . "\0" . '%d sukcesis','%d skipped'=>'%d preterlasita' . "\0" . '%d preterlasitaj','%d failed'=>'%d malsukcesis' . "\0" . '%d malsukcesis','%d not yet tried'=>'%d ankoraŭ ne provita' . "\0" . '%d ankoraŭ ne provitaj','%1$s nothing to do.'=>'%1$s nenio farenda.','%1$s %2$s.'=>'%1$s %2$s.','Bulk download:'=>'Amasa elŝuto:','Bulk update:'=>'Amasa ĝisdatigo:','Bulk request:'=>'Amasa peto:','per day'=>'tage','Wrong meaning'=>'Malĝusta signifo','Wrong term'=>'Malĝusta termino','Broken placeholder'=>'Difektita lokokupilo','Wrong for this context'=>'Malĝusta por ĉi tiu kunteksto','Wrong plural form'=>'Malĝusta plurala formo','Negation reversed'=>'Inversigita negacio','Translation does not load'=>'La traduko ne ŝargiĝas','problem report categoryOther'=>'Alia','%1$s (%2$s): %3$s'=>'%1$s (%2$s): %3$s','Continuing…'=>'Daŭrigante…','Continue next batch (%d left)'=>'Daŭrigi la sekvan aron (restas %d)','Search components'=>'Serĉi komponantojn','These are the languages this site uses. You can change them in %s.'=>'Ĉi tiuj estas la lingvoj uzataj de ĉi tiu retejo. Vi povas ŝanĝi ilin en %s.','Upload this component?'=>'Ĉu alŝuti ĉi tiun komponanton?','There is no upload waiting for confirmation.'=>'Neniu alŝuto atendas konfirmon.','Back'=>'Reen','To translate this component, Babilim needs its source.'=>'Por traduki ĉi tiun komponanton, Babilim bezonas ĝian fonton.','The entire plugin or theme directory of %1$s (version %2$s) will be uploaded to Babilim.'=>'La tuta dosierujo de la kromprogramo aŭ etoso %1$s (versio %2$s) estos alŝutita al Babilim.','If that directory contains keys, logs or customer data, they will be uploaded too. The service removes common sensitive files (configuration, environment, database dumps, logs, keys) but cannot guarantee it finds everything.'=>'Se tiu dosierujo enhavas ŝlosilojn, protokolojn aŭ klientajn datumojn, ili ankaŭ estos alŝutitaj. La servo forigas oftajn sentemajn dosierojn (agordojn, medion, datumbazajn kopiojn, protokolojn, ŝlosilojn), sed ne povas garantii, ke ĝi trovas ĉion.','The upload is kept until you ask Babilim to delete it.'=>'La alŝuto estas konservata ĝis vi petas al Babilim forigi ĝin.','It is stored by the service\'s hosting provider and processed by AI models to produce the translation.'=>'Ĝi estas konservata de la gastiga provizanto de la servo kaj prilaborata de AI-modeloj por produkti la tradukon.','The original text and the translations made from it will be provided to other sites that install the same version.'=>'La originala teksto kaj la tradukoj faritaj el ĝi estos provizitaj al aliaj retejoj, kiuj instalas la saman version.','By continuing you confirm that you have the right to upload this component.'=>'Daŭrigante vi konfirmas, ke vi havas la rajton alŝuti ĉi tiun komponanton.','Upload and request'=>'Alŝuti kaj peti','Uploading…'=>'Alŝutante…','Cancel'=>'Nuligi','Uploading'=>'Alŝutante','There is no upload in progress.'=>'Neniu alŝuto estas progresanta.','Uploading part %1$d of %2$d…'=>'Alŝutante parton %1$d el %2$d…','Continue'=>'Daŭrigi','Confirm'=>'Konfirmi','Remove'=>'Forigi','Roll back'=>'Retroigi','Nothing to confirm.'=>'Nenio por konfirmi.','Choose a language'=>'Elektu lingvon','Roll back and report'=>'Retroigi kaj raporti','Report a problem'=>'Raporti problemon','Nothing to choose.'=>'Nenio por elekti.','%1$s: %2$s. Choose the language.'=>'%1$s: %2$s. Elektu la lingvon.','Supplementary translations'=>'Suplementaj tradukoj','Each component\'s own contribution to each locale\'s shared default-domain supplement.'=>'La propra kontribuo de ĉiu komponanto al la komuna suplemento de la defaŭlta domajno de ĉiu lokaĵaro.','Component'=>'Komponanto','Language'=>'Lingvo','Included in index'=>'Inkluzivita en la indekso','Entries'=>'Enskriboj','Conflicting keys'=>'Konfliktaj ŝlosiloj','Yes'=>'Jes','No — component inactive'=>'Ne — komponanto neaktiva','No — installed version differs from the active one'=>'Ne — la instalita versio malsamas de la aktiva','No — component removed'=>'Ne — komponanto forigita','No'=>'Ne','Only a network administrator can do this, because it changes translation files shared by every site on this network.'=>'Nur reta administranto povas fari tion, ĉar ĝi ŝanĝas tradukdosierojn komunajn al ĉiuj retejoj en ĉi tiu reto.','Babilim could not finish verifying this site (the service could not reach it back). Registration is paused.'=>'Babilim ne povis fini la kontrolon de ĉi tiu retejo (la servo ne povis kontakti ĝin reen). La registriĝo estas paŭzigita.','This site already has an active registration that can no longer be recovered automatically.'=>'Ĉi tiu retejo jam havas aktivan registriĝon, kiu ne plu povas esti reakirita aŭtomate.','Restart registration'=>'Rekomenci registriĝon','Babilim settings'=>'Agordoj de Babilim','General'=>'Ĝeneralaj','Advanced'=>'Altnivelaj','Languages'=>'Lingvoj','Automatic installs'=>'Aŭtomata instalado','Install available translations automatically'=>'Instali disponeblajn tradukojn aŭtomate','On the free plan, only components that already use one of your free slots are installed automatically, so no new slot is taken.'=>'En la senpaga plano, nur komponantoj, kiuj jam uzas unu el viaj senpagaj lokoj, estas instalataj aŭtomate, do neniu nova loko estas okupata.','This site is part of a multisite network, which does not install new translations automatically. Translations that are already installed are still updated.'=>'Ĉi tiu retejo apartenas al multretejo-reto, kiu ne instalas novajn tradukojn aŭtomate. Jam instalitaj tradukoj tamen ankoraŭ estas ĝisdatigataj.','Custom overrides'=>'Propraj superregoj','Keep my own translation overrides when purging everything or uninstalling this plugin.'=>'Konservi miajn proprajn tradukajn superregojn dum forviŝo de ĉio aŭ malinstalado de ĉi tiu kromprogramo.','Translation files you put in %s always take priority over Babilim\'s. They are kept unless you uncheck this.'=>'Tradukdosieroj, kiujn vi metas en %s, ĉiam havas prioritaton super tiuj de Babilim. Ili estas konservataj krom se vi malmarkas ĉi tion.','Uninstall'=>'Malinstali','Delete all Babilim data on uninstall'=>'Forigi ĉiujn datumojn de Babilim ĉe malinstalo','Off by default: deleting the plugin keeps this site\'s identity, so a reinstall can reuse it.'=>'Defaŭlte malŝaltita: forigo de la kromprogramo konservas la identecon de ĉi tiu retejo, por ke reinstalo povu reuzi ĝin.','Account'=>'Konto','Save changes'=>'Konservi ŝanĝojn','Disable Babilim'=>'Malŝalti Babilim','Installed translations are kept, but no further checks or downloads will run.'=>'Instalitaj tradukoj estas konservataj, sed pliaj kontroloj aŭ elŝutoj ne plu okazos.','Disable Babilim? Installed translations are kept, but no further checks or downloads will run.'=>'Ĉu malŝalti Babilim? Instalitaj tradukoj estas konservataj, sed pliaj kontroloj aŭ elŝutoj ne plu okazos.','This site is not registered with Babilim yet.'=>'Ĉi tiu retejo ankoraŭ ne estas registrita ĉe Babilim.','This site is already licensed. Reload the page.'=>'Ĉi tiu retejo jam havas licencon. Reŝargu la paĝon.','Checkout is not available for this site right now.'=>'Pagprocezo ne disponeblas por ĉi tiu retejo nuntempe.','Could not start checkout: %s'=>'Ne eblis komenci pagprocezon: %s','Babilim is not enabled.'=>'Babilim ne estas ebligita.','Not registered yet'=>'Ankoraŭ ne registrita','Not verified'=>'Ne kontrolita','Verified'=>'Kontrolita','Status'=>'Stato','Licensed'=>'Rajtigita','Partner'=>'Partnero','Free'=>'Senpaga','License'=>'Licenco','Upgrade this site'=>'Gradaltigi ĉi tiun retejon','One-time purchase for this site: %1$s %2$s. Includes all future translation updates. Payment is handled by Paddle in a new tab.'=>'Unufoja aĉeto por ĉi tiu retejo: %1$s %2$s. Inkluzivas ĉiujn estontajn ĝisdatigojn de tradukoj. La pagon traktas Paddle en nova langeto.','This issues a new restore code and the previous one stops working. Continue?'=>'Ĉi tio eldonas novan restaŭran kodon kaj la antaŭa ĉesas funkcii. Ĉu daŭrigi?','Show a new restore code'=>'Montri novan restaŭran kodon','rc_…'=>'rc_…','Restore code'=>'Restaŭra kodo','Restore purchase'=>'Restaŭri aĉeton','Bought a license for this domain before? Enter the restore code you received at checkout.'=>'Ĉu vi aĉetis licencon por ĉi tiu domajno antaŭe? Enigu la restaŭran kodon, kiun vi ricevis ĉe la pagprocezo.','That does not look like a restore code.'=>'Tio ne similas restaŭran kodon.','This restore code was not recognised for this site.'=>'Ĉi tiu restaŭra kodo ne estis rekonita por ĉi tiu retejo.','Too many attempts. Try again tomorrow.'=>'Tro multaj provoj. Provu denove morgaŭ.','This site must be verified first.'=>'Ĉi tiu retejo devas unue esti kontrolita.','Could not restore the purchase: %s'=>'Ne eblis restaŭri la aĉeton: %s','Purchase restored. This site is now licensed.'=>'Aĉeto restaŭrita. Ĉi tiu retejo nun estas rajtigita.','This site has no purchase to show a code for.'=>'Ĉi tiu retejo ne havas aĉeton, por kiu montri kodon.','Could not show a new restore code: %s'=>'Ne eblis montri novan restaŭran kodon: %s','Your new restore code: %s. Keep it somewhere safe — the previous code no longer works.'=>'Via nova restaŭra kodo: %s. Konservu ĝin en sekura loko — la antaŭa kodo ne plu funkcias.','What is sent when Babilim checks this site'=>'Kio estas sendata kiam Babilim kontrolas ĉi tiun retejon','(detected)'=>'(detektita)','No language is managed yet.'=>'Ankoraŭ neniu lingvo estas administrata.','Babilim adds translations for every language checked here.'=>'Babilim aldonas tradukojn por ĉiu ĉi tie markita lingvo.','Add another language'=>'Aldoni alian lingvon','Choose a language…'=>'Elektu lingvon…','Could not load the full WordPress.org locale list from the service, so no other language can be added right now.'=>'Ne eblis ŝargi la plenan liston de lokaĵaroj de WordPress.org el la servo, do neniu alia lingvo povas esti aldonita nun.','Theme'=>'Etoso','Plugin'=>'Kromprogramo','Free quota'=>'Senpaga kvoto','Downloads: %1$d/%2$d (%3$s)'=>'Elŝutoj: %1$d/%2$d (%3$s)','Supplementary translation index'=>'Suplementa traduka indekso','Built'=>'Konstruita','Included'=>'Inkluzivita','Excluded'=>'Ekskluzivita','Already in WordPress core'=>'Jam en la kerno de WordPress','Supplementary translation maintenance'=>'Prizorgado de suplementaj tradukoj','Maintenance status is not available right now.'=>'Prizorga stato ne disponeblas nun.','A cleanup was paused on %1$s: %2$s. Nothing was deleted.'=>'Purigado estis paŭzigita je %1$s: %2$s. Nenio estis forigita.','Last cleanup on %1$s: %2$d newly marked, %3$d file(s) deleted, %4$d record(s) removed.'=>'Lasta purigado je %1$s: %2$d nove markitaj, %3$d dosiero(j) forigita(j), %4$d registro(j) forigita(j).','No cleanup has run yet.'=>'Ankoraŭ neniu purigado okazis.','A translation-index write conflicted with another request on %1$s (%2$s) and was not applied; the most recent version was kept.'=>'Skribo al la traduka indekso konfliktis kun alia peto je %1$s (%2$s) kaj ne estis aplikita; la plej freŝa versio estis konservita.','A translation-index write on %1$s (%2$s) could not be completed and was not applied (%3$s).'=>'Skribo al la traduka indekso je %1$s (%2$s) ne povis esti finita kaj ne estis aplikita (%3$s).','Maintenance'=>'Prizorgado','Rebuild index now'=>'Rekonstrui indekson nun','Sweep now'=>'Skani nun','Danger zone'=>'Danĝera zono','Removes every language file Babilim has installed for every plugin and theme on this site.'=>'Forigas ĉiun lingvan dosieron, kiun Babilim instalis por ĉiu kromprogramo kaj etoso en ĉi tiu retejo.','Remove everything Babilim installed? This deletes every language file it installed for every plugin and theme on this site.'=>'Ĉu forigi ĉion, kion Babilim instalis? Ĉi tio forigas ĉiun lingvan dosieron, kiun Babilim instalis por ĉiu kromprogramo kaj etoso en ĉi tiu retejo.','Remove everything Babilim installed'=>'Forigi ĉion, kion Babilim instalis','This string is too long to be sent as a report, so no report form is offered for it.'=>'Ĉi tiu signoĉeno estas tro longa por esti sendita kiel raporto, do neniu raporta formularo estas proponata por ĝi.','Category'=>'Kategorio','Choose a category…'=>'Elektu kategorion…','Roll back and send report'=>'Retroigi kaj sendi raporton','Send report'=>'Sendu raporton','Some of this component\'s text is hard-coded by its author and can\'t be translated by a language pack.'=>'Parto de la teksto de ĉi tiu komponanto estas fikskodita de ĝia aŭtoro kaj ne povas esti tradukita per lingvopakaĵo.','WordPress.org'=>'WordPress.org','Bundled with the theme'=>'Kunpakita kun la etoso','Bundled with the plugin'=>'Kunpakita kun la kromprogramo','Upload was not accepted'=>'Alŝuto ne estis akceptita','Upload expired before it finished'=>'Alŝuto eksvalidiĝis antaŭ ol finiĝi','No translation'=>'Neniu traduko','Upload in progress — continue or cancel'=>'Alŝuto okazas — daŭrigu aŭ nuligu','Scheduled, waiting to be processed'=>'Planita, atendas traktadon','Translating…'=>'Tradukado…','Translation failed'=>'Traduko malsukcesis','Free quota used'=>'Senpaga kvoto uzita','Needs a paid license'=>'Bezonas pagitan licencon','Not supported'=>'Ne subtenata','Status unknown'=>'Stato nekonata','translation statusInstalled'=>'Instalita','Update available'=>'Ĝisdatigo disponebla','Removed after a failed integrity check'=>'Forigita post malsukcesa kontrolo de integreco','Installed · built for %s, new version scheduled'=>'Instalita · konstruita por %s, nova versio planita','Installed · built for a different version, new version scheduled'=>'Instalita · konstruita por alia versio, nova versio planita','Installed · built for %s, translating the new version…'=>'Instalita · konstruita por %s, la nova versio estas tradukata…','Installed · built for a different version, translating the new version…'=>'Instalita · konstruita por alia versio, la nova versio estas tradukata…','Installed · built for %1$s, this site has %2$s'=>'Instalita · konstruita por %1$s, ĉi tiu retejo havas %2$s','Installed · built for %s'=>'Instalita · konstruita por %s','Installed · built for a different version'=>'Instalita · konstruita por alia versio','Installed · built for %s, new version failed'=>'Instalita · kreita por %s, nova versio malsukcesis','Installed · built for a different version, new version failed'=>'Instalita · kreita por alia versio, nova versio malsukcesis','Installed · built for %s, new version needs a paid license'=>'Instalita · konstruita por %s, nova versio bezonas pagitan licencon','Installed · built for a different version, new version needs a paid license'=>'Instalita · konstruita por alia versio, nova versio bezonas pagitan licencon','Installed · built for %s, free quota used'=>'Instalita · konstruita por %s, senpaga kvoto uzita','Installed · built for a different version, free quota used'=>'Instalita · konstruita por alia versio, senpaga kvoto uzita','translation statusAvailable'=>'Havebla','Installed · %s'=>'Instalita · %s','Available · %s'=>'Havebla · %s','Update'=>'Ĝisdatigi','Download'=>'Elŝuti','Updating…'=>'Ĝisdatigante…','Downloading…'=>'Elŝutante…','Retry request'=>'Reprovi peton','Request newer translation'=>'Petu pli novan tradukon','Request translation'=>'Peti tradukon','Requesting…'=>'Petante…','Requesting a translation uses one of your free slots, unless this component already uses one. A failed translation does not give the slot back.'=>'Peti tradukon uzas unu el viaj senpagaj lokoj, krom se ĉi tiu komponanto jam uzas unu. Malsukcesa traduko ne redonas la lokon.','If this component does not use one of your free slots yet, requesting a translation uses one. A failed translation does not give the slot back. Continue?'=>'Se ĉi tiu komponanto ankoraŭ ne uzas unu el viaj senpagaj lokoj, peti tradukon uzos unu. Malsukcesa traduko ne redonas la lokon. Ĉu daŭrigi?','No plugins or themes found.'=>'Neniuj kromprogramoj aŭ etosoj trovitaj.','Clear filters'=>'Forigi filtrilojn','No components match these filters. %s'=>'Neniu komponanto kongruas kun ĉi tiuj filtriloj. %s','Select all'=>'Elekti ĉion','All'=>'Ĉio','Available'=>'Havebla','Updates'=>'Ĝisdatigoj','Requestable'=>'Petebla','Installed'=>'Instalita','Plugins'=>'Kromprogramoj','Themes'=>'Etosoj','All languages'=>'Ĉiuj lingvoj','%d to install'=>'%d por instali' . "\0" . '%d por instali','Language:'=>'Lingvo:','Bulk actions apply to every matching language of each selected component.'=>'Amasaj agoj aplikiĝas al ĉiu kongrua lingvo de ĉiu elektita komponanto.','Bulk actions apply only to the selected language of each selected component.'=>'Amasaj agoj aplikiĝas nur al la elektita lingvo de ĉiu elektita komponanto.','Version %s'=>'Versio %s','Theme · %s'=>'Etoso · %s','Plugin · %s'=>'Kromprogramo · %s','Remove the %2$s translation of %1$s from this site?'=>'Ĉu forigi la tradukon de %1$s en %2$s el ĉi tiu retejo?','Roll back the %2$s translation of %1$s to the previous build?'=>'Ĉu restarigi la tradukon de %1$s en %2$s al la antaŭa kompilaĵo?','%1$s: %2$s'=>'%1$s: %2$s','%1$s: %2$s (%3$s)'=>'%1$s: %2$s (%3$s)','The registration challenge is not in the expected form.'=>'La registra defio ne havas la atendatan formon.','That is not a valid build identifier.'=>'Tio ne estas valida identigilo de kompilaĵo.','Refusing to write outside the Babilim language-file directory.'=>'Rifuzo skribi ekster la dosierujo de lingvodosieroj de Babilim.','Could not write the downloaded package to disk.'=>'Ne eblis skribi la elŝutitan pakaĵon al la disko.','Unexpected HTTP %d response.'=>'Neatendita HTTP-respondo %d.','This site\'s URL, so the service can verify you own it.'=>'La URL de ĉi tiu retejo, por ke la servo povu kontroli ke vi posedas ĝin.','Your WordPress version, to serve compatible translation files.'=>'Via versio de WordPress, por servi kongruajn tradukdosierojn.','Your PHP version, for compatibility.'=>'Via versio de PHP, por kongruo.','This plugin\'s own version, so the service can tell you to update it if it\'s too old to talk to.'=>'La versio de ĉi tiu kromprogramo mem, por ke la servo povu diri al vi ĝisdatigi ĝin se ĝi estas tro malnova por komuniki.','This site\'s configured locale.'=>'La agordita lokaĵaro de ĉi tiu retejo.','Every locale in use on this site (site locale, installed language packs, user locales, and any you add manually). No locale is treated differently from another.'=>'Ĉiu lokaĵaro uzata en ĉi tiu retejo (retejlokaĵaro, instalitaj lingvopakaĵoj, lokaĵaroj de uzantoj kaj ĉiuj, kiujn vi aldonas permane). Neniu lokaĵaro estas traktata alie ol alia.','(a public key generated for this site)'=>'(publika ŝlosilo generita por ĉi tiu retejo)','This site\'s install public key, used to prove requests genuinely come from this site. Only the public half is ever sent.'=>'La publika ŝlosilo de ĉi tiu instalaĵo, uzata por pruvi ke petoj vere venas de ĉi tiu retejo. Nur la publika duono iam estas sendata.','Every installed plugin/theme: its slug, version, text domain(s), whether it\'s a wp.org listing, its own bundled locales, and which locales you\'ve already installed a Babilim translation for.'=>'Ĉiu instalita kromaĵo/etoso: ĝia slug, versio, text domain(s) (teksto-domajno/j), ĉu ĝi estas listigita ĉe wp.org, ĝiaj propraj kunpakitaj lokaĵaroj, kaj por kiuj lokaĵaroj vi jam instalis tradukon de Babilim.','Only when you confirm an upload for a plugin or theme that is not on WordPress.org: that component\'s entire directory, as a zip.'=>'Nur kiam vi konfirmas alŝuton por kromprogramo aŭ etoso, kiu ne estas en WordPress.org: la tuta dosierujo de tiu komponanto, kiel zip.','(generic codes and coordinates only)'=>'(nur ĝeneralaj kodoj kaj koordinatoj)','Up to 20 pending diagnostic events (e.g. a file that failed its integrity check), each just a code, component, and locale, and never any string content or translated text.'=>'Ĝis 20 pritraktotaj diagnozaj eventoj (ekz. dosiero, kiu malsukcesis en sia kontrolo de integreco), ĉiu nur kun kodo, komponanto kaj lokaĵaro, kaj neniam kun ajna enhavo de ĉenoj aŭ tradukita teksto.','Unsafe locale: %s'=>'Nesekura lokaĵaro: %s','Manifest unavailable: %s'=>'Manifesto nedisponebla: %s','Could not determine active components; the existing merged index was left unchanged.'=>'Ne eblis determini aktivajn komponantojn; la ekzistanta kunfandita indekso restis neŝanĝita.','Could not determine installed plugins/themes; sweep skipped, nothing was deleted.'=>'Ne eblis determini instalitajn kromprogramojn/etosojn; la balaado estis preterlasita, nenio estis forigita.','Sweep aborted without orphaning anything: %s.'=>'La balaado estis ĉesigita sen orfigi ion ajn: %s.','The cleanup ran, but some of its changes could not be recorded in the translation index; the next cleanup will retry them.'=>'La purigo okazis, sed kelkaj ĝiaj ŝanĝoj ne povis esti registritaj en la traduka indekso; la sekva purigo reprovos ilin.','component kind in the sweep brake messagetheme'=>'etoso','component kind in the sweep brake messageplugin'=>'kromaĵo','it would orphan every managed %1$s component (%2$d of %2$d)'=>'ĝi orfigus ĉiun administratan komponanton de speco %1$s (%2$d el %2$d)','it would orphan %1$d of %2$d managed components (more than half)'=>'ĝi orfigus %1$d el %2$d administrataj komponantoj (pli ol duono)','The merged index for \'%s\' was rebuilt, but the translation index could not record it; the next rebuild will retry.'=>'La kunfandita indekso por \'%s\' estis rekonstruita, sed la traduka indekso ne povis registri ĝin; la sekva rekonstruo reprovos.','Could not write the staged merged index.'=>'Ne eblis skribi la surscenigitan kunfanditan indekson.','Re-parsed entry count did not match the built index.'=>'La nombro de re-analizitaj eroj ne kongruis kun la konstruita indekso.','Could not move the merged index for \'%s\' into place; the previous served index (if any) was removed rather than left half-updated. No default-domain supplement is served for this locale until the next successful rebuild.'=>'Ne eblis movi la kunfanditan indekson por \'%s\' al ĝia loko; la antaŭa servata indekso (se ekzistis) estis forigita anstataŭ lasi ĝin duonĝisdatigita. Neniu suplemento de la defaŭlta domajno estos servata por ĉi tiu lokaĵaro ĝis la sekva sukcesa rekonstruo.','Could not open zip: %s'=>'Ne eblis malfermi zip: %s','Zip has no manifest.json.'=>'La zip ne havas manifest.json.','manifest.json in the zip is not valid JSON.'=>'manifest.json en la zip ne estas valida JSON.','manifest.json\'s \'%s\' does not match the expected value.'=>'La \'%s\' de manifest.json ne kongruas kun la atendata valoro.','Another installation is running; try again in a moment.'=>'Alia instalado funkcias; reprovu post momento.','Not a valid server_build_id: %s'=>'Ne valida server_build_id: %s','The package manifest\'s kind \'%1$s\' does not match the requested kind \'%2$s\'.'=>'La speco \'%1$s\' de la pakaĵa manifesto ne kongruas kun la petita speco \'%2$s\'.','The package\'s text domain \'%1$s\' does not match this site\'s copy of the component (\'%2$s\'), so it was not installed.'=>'La teksta domajno \'%1$s\' de la pakaĵo ne kongruas kun la kopio de la komponanto en ĉi tiu retejo (\'%2$s\'), do ĝi ne estis instalita.','The given domain \'%1$s\' matches neither the package manifest\'s own slug \'%2$s\' nor its text_domain \'%3$s\'.'=>'La donita domajno \'%1$s\' kongruas nek kun la propra slug de la pakaĵa manifesto \'%2$s\' nek kun ĝia text_domain \'%3$s\'.','Unsafe slug: %s'=>'Nesekura slug: %s','Unsafe text_domain: %s'=>'Nesekura text_domain: %s','The package has no %s for its own text domain.'=>'La pakaĵo ne havas %s por sia propra Teksto-domajno.','manifest.json is missing or has an invalid \'%s\'.'=>'manifest.json mankas aŭ havas nevalidan \'%s\'.','manifest.json is missing or has an invalid \'entries\'.'=>'manifest.json mankas aŭ havas nevalidan \'entries\'.','manifest.json is missing or has an invalid \'files\'.'=>'manifest.json mankas aŭ havas nevalidan \'files\'.','manifest.json is missing or has an invalid \'extra_domains\'.'=>'manifest.json mankas aŭ havas nevalidan \'extra_domains\'.','manifest.json is missing or has an invalid \'build_no\'.'=>'manifest.json mankas aŭ havas nevalidan \'build_no\'.','manifest.json\'s \'server_build_id\' is not a valid build id.'=>'La \'server_build_id\' de manifest.json ne estas valida identigilo de kompilaĵo.','manifest.json\'s \'contract\' is not a valid version string.'=>'La \'contract\' de manifest.json ne estas valida versia ĉeno.','manifest.json\'s \'status\' must be \'published\'.'=>'La \'Stato\' de manifest.json devas esti \'published\'.','manifest.json\'s \'kind\' must be \'plugin\' or \'theme\'.'=>'La \'kind\' de manifest.json devas esti \'plugin\' aŭ \'theme\' (Etoso).','manifest.json has an invalid \'default_domain_entries\'.'=>'manifest.json havas nevalidan \'default_domain_entries\'.','manifest.json has an invalid \'default_domain_files\'.'=>'manifest.json havas nevalidan \'default_domain_files\'.','expected_manifest is missing or has an invalid \'%s\'.'=>'expected_manifest mankas aŭ havas nevalidan \'%s\'.','expected_manifest\'s \'server_build_id\' is not a valid build id.'=>'La \'server_build_id\' de expected_manifest ne estas valida identigilo de kompilaĵo.','No record for %s'=>'Neniu registro por %s','One or more served files no longer match the manifest.'=>'Unu aŭ pluraj servataj dosieroj ne plu kongruas kun la manifesto.','No previous build to roll back to.'=>'Ne ekzistas antaŭa kompilaĵo, al kiu reveni.','The change could not be recorded in the translation index; please try again.'=>'La ŝanĝo ne povis esti registrita en la traduka indekso; bonvolu reprovi.','Unknown kind: %s'=>'Nekonata speco: %s','Unsafe domain: %s'=>'Nesekura domajno: %s','The text domain \'%1$s\' (%2$s) is already served for another installed component (%3$s); nothing was installed.'=>'La Teksto-domajno \'%1$s\' (%2$s) jam estas servata por alia instalita komponanto (%3$s); nenio estis instalita.','Rolling back would overwrite \'%1$s\' (%2$s), which is now served for another installed component (%3$s); nothing was changed.'=>'Retrorulo superskribus \'%1$s\' (%2$s), kiu nun estas servata por alia instalita komponanto (%3$s); nenio estis ŝanĝita.','Zip is missing expected file: %s'=>'Al la zip mankas atendata dosiero: %s','sha256 mismatch for %s'=>'sha256 ne kongruas por %s','The package declares no main translation file.'=>'La pako deklaras neniun ĉefan tradukdosieron.','Zip is missing expected default file: %s'=>'Al la zip mankas atendata default-dosiero: %s','sha256 mismatch for default/%s'=>'sha256 ne kongruas por default/%s','Could not stage %s'=>'Ne eblis prepari %s en provizora loko por instalado.','Could not stage default/%s'=>'Ne eblis prepari default/%s en provizora loko por instalado.','Entry count mismatch for %s'=>'Nekongrua nombro de eroj por %s','Could not verify entry count for %s'=>'Ne eblis kontroli la nombron de eroj por %s','l10n.php entry count mismatch for %s'=>'La nombro de eroj en l10n.php ne kongruas por %s','Default supplement entry count mismatch.'=>'Nekongrua nombro de eroj en la default-suplemento.','The package produced no servable main translation file.'=>'La pako ne produktis ĉefan tradukdosieron, kiun la sistemo povas disponigi.','Could not prepare %s for rollback.'=>'Ne eblis prepari %s por retroigo.','Could not back up %s before replacing it.'=>'Ne eblis sekurkopii %s antaŭ ol anstataŭigi ĝin.','Could not move %s into place.'=>'Ne eblis movi %s al ĝia loko.','Could not read %s back after moving it into place.'=>'Ne eblis relegi %s post movo al ĝia loko.','English (United States)'=>'Angla (Usono)','Babilim_Manifest is unavailable: %s'=>'Babilim_Manifest ne disponeblas: %s','could not read _manifest.json: %s'=>'ne eblis legi _manifest.json: %s','failed to parse _manifest.json: %s'=>'malsukcesis analizi _manifest.json: %s','_manifest.json has an unexpected structure'=>'_manifest.json havas neatenditan strukturon','Could not create the package archive.'=>'Ne eblis krei la pakaĵan arĥivon.','No writable temporary directory is available for packaging.'=>'Neniu skribebla provizora dosierujo disponeblas por pakado.','A file in the component could not be read, so it was not packaged.'=>'Dosiero en la komponanto ne estis legebla, tial ĝi ne estis pakita.','Only plugins and themes can be packaged.'=>'Nur kromprogramoj kaj temoj povas esti pakitaj.','The component\'s main file was not found.'=>'La ĉefa dosiero de la komponanto ne troviĝis.','The component is not inside the plugins or themes directory.'=>'La komponanto ne estas en la dosierujo de kromprogramoj aŭ temoj.','Babilim ran out of time for this step and will continue on the next check.'=>'Babilim restis sen tempo por ĉi tiu paŝo kaj daŭrigos ĉe la sekva kontrolo.','Babilim could not verify this site, so nothing is downloaded or installed until verification succeeds.'=>'Babilim ne povis kontroli ĉi tiun retejon, tial nenio estas elŝutata aŭ instalata ĝis la kontrolo sukcesos.','Registration response was missing required fields.'=>'En la registra respondo mankis postulataj kampoj.','No pending challenge to verify.'=>'Neniu pritraktota defio por kontroli.','Verify response was missing site_token.'=>'La respondo de kontrolo ne enhavis site_token.','Rotate-token response was missing site_token.'=>'La respondo de rotacio de ĵetono ne enhavis site_token.','nonce must be a hexadecimal string.'=>'nonce devas esti deksesuma ĉeno.','No pending challenge for this nonce.'=>'Neniu pritraktota defio por tiu ĉi nonce.','Too many requests.'=>'Tro multaj petoj.','The service asked this site to wait before syncing again.'=>'La servo petis, ke tiu ĉi retejo atendu antaŭ ol sinkronigi denove.','This site has %1$d components across %2$d languages, which needs %3$d check batches; Babilim can handle at most %4$d per run. Reduce the managed languages in Settings or deactivate unused plugins and themes, then press Check again now.'=>'Tiu ĉi retejo havas %1$d komponantojn en %2$d lingvoj, kio postulas %3$d kontrolajn aron(j)n; Babilim povas trakti maksimume %4$d por ĉiu ruligo. Malpliigu la administratajn lingvojn en Agordoj aŭ malaktivigu neuzatajn kromprogramojn kaj etosojn, poste premu Kontroli denove nun.','Babilim could not finish checking this site.'=>'Babilim ne povis fini kontroli ĉi tiun retejon.','This site\'s address is too long for Babilim to register.'=>'La adreso de ĉi tiu retejo estas tro longa por ke Babilim registru ĝin.','This site\'s locale code is not one Babilim can register.'=>'La lingva kodo de tiu ĉi retejo ne estas registrebla de Babilim.','The download response was missing a usable location.'=>'La elŝuta respondo ne enhavis uzeblan lokon.','The service\'s upload offer was incomplete.'=>'La alŝuta propono de la servo estis nekompleta.','This component is larger than the service accepts, so it cannot be uploaded.'=>'Ĉi tiu komponanto estas pli granda ol la servo akceptas, tial ĝi ne povas esti alŝutita.','The packaged component could not be read.'=>'La pakita komponanto ne estis legebla.','A part of the upload kept failing, so the upload was cancelled.'=>'Parto de la alŝuto daŭre malsukcesis, tial la alŝuto estis nuligita.','Could not read: %s'=>'Ne eblis legi: %s']];